SELECT			
	A.TRADE_ID		
FROM			
	BOK_BATCH_TASK_TODO BT ,TRD_PRODUCT_DEAL A, BOK_BOOKSET_DATE C, TRD_PRODUCT_DEAL_ADD  D,BOK_DEAL_ACCOUNTING E
