	A.TRADE_DATE = C.BOOKSET_DATE
	AND A.BUSI_TYPE IN ('26')
	AND D.GEN_TYPE = '03'
	AND A.TRADE_ID = D.TRADE_ID
	AND E.BUSI_NO = A.TRADE_ID


   		AND A.FINPROD_TYPE = #{finprodType}


	AND E.BUSI_TABLE = '02'
	AND C.BOOKSET_ID = E.BOOKSET_ID
